%[text] # BEV System Model - Simulation Case
modelName = "BEV_system_model";
load_system(modelName)
BEV_useBasic %[output:67351675]
VehSpdRef_loadCase_HighSpeed( ... %[output:group:2c519ff2] %[output:7da780e8]
  ModelName = modelName, ... %[output:7da780e8]
  TargetSubsystemPath = "/Controller & Environment/Vehicle speed reference") %[output:group:2c519ff2] %[output:7da780e8]
simOut = sim(modelName);
simData = extractTimetable(simOut.logsout);
fig = BEV_ResultsCompactPlot(SimData = simData, PlotTemperature = false); %[output:06127530]
